function setupCommentSpacing() {
	const config: boolean | undefined = vscode.workspace.getConfiguration('editor.comments').get('insertSpace');
	if (config) {
		startCommentStylesheet = '/* ';
		endCommentStylesheet = ' */';
		startCommentHTML = '<!-- ';
		endCommentHTML = ' -->';
	} else {
		startCommentStylesheet = '/*';
		endCommentStylesheet = '*/';
		startCommentHTML = '<!--';
		endCommentHTML = '-->';
	}
}
